insert into public.products (id, slug, name, category_id, description, composition, care, price_cents, image_url, image_alt, active)
values
('blusa-satinada-caroni', 'blusa-satinada-caroni', 'DEMO · Blusa satinada Caroní', 'demo-superiores', 'Producto ficticio de demostración. No es inventario real y no está disponible para compra. Blusa de satén con cuello redondo y manga corta. Cae suelta sin pegarse.', '', '', 2600, 'https://reinaldogocode.github.io/ProyectOne/demo-products/blusa-satinada-caroni.svg', 'Ilustración de demostración: DEMO · Blusa satinada Caroní', true),
('camisa-cuadros-andes', 'camisa-cuadros-andes', 'DEMO · Camisa de cuadros Andes', 'demo-superiores', 'Producto ficticio de demostración. No es inventario real y no está disponible para compra. Camisa de cuadros en algodón ligero, corte relajado y bolsillo frontal.', '', '', 3000, 'https://reinaldogocode.github.io/ProyectOne/demo-products/camisa-cuadros-andes.svg', 'Ilustración de demostración: DEMO · Camisa de cuadros Andes', true),
('camisa-lino-margarita', 'camisa-lino-margarita', 'DEMO · Camisa de lino Margarita', 'demo-superiores', 'Producto ficticio de demostración. No es inventario real y no está disponible para compra. Camisa fresca de lino para el calor de la costa. Corte recto y manga larga recogible.', '', '', 2800, 'https://reinaldogocode.github.io/ProyectOne/demo-products/camisa-lino-margarita.svg', 'Ilustración de demostración: DEMO · Camisa de lino Margarita', true),
('camisa-oversize-catuaro', 'camisa-oversize-catuaro', 'DEMO · Camisa oversize Catuaro', 'demo-superiores', 'Producto ficticio de demostración. No es inventario real y no está disponible para compra. Camisa oversize de caída suave, pensada para usar suelta o anudada.', '', '', 3200, 'https://reinaldogocode.github.io/ProyectOne/demo-products/camisa-oversize-catuaro.svg', 'Ilustración de demostración: DEMO · Camisa oversize Catuaro', true),
('camiseta-basica-pampatar', 'camiseta-basica-pampatar', 'DEMO · Camiseta básica Pampatar', 'demo-superiores', 'Producto ficticio de demostración. No es inventario real y no está disponible para compra. Camiseta de algodón peinado, cuello redondo y corte recto.', '', '', 1400, 'https://reinaldogocode.github.io/ProyectOne/demo-products/camiseta-basica-pampatar.svg', 'Ilustración de demostración: DEMO · Camiseta básica Pampatar', true),
('chaqueta-denim-la-guaira', 'chaqueta-denim-la-guaira', 'DEMO · Chaqueta denim La Guaira', 'demo-chaquetas', 'Producto ficticio de demostración. No es inventario real y no está disponible para compra. Chaqueta de denim rígido, corte oversize y bolsillos frontales.', '', '', 4800, 'https://reinaldogocode.github.io/ProyectOne/demo-products/chaqueta-denim-la-guaira.svg', 'Ilustración de demostración: DEMO · Chaqueta denim La Guaira', true),
('chaqueta-lino-choroni', 'chaqueta-lino-choroni', 'DEMO · Chaqueta de lino Choroní', 'demo-chaquetas', 'Producto ficticio de demostración. No es inventario real y no está disponible para compra. Chaqueta ligera de lino para las noches frescas.', '', '', 4500, 'https://reinaldogocode.github.io/ProyectOne/demo-products/chaqueta-lino-choroni.svg', 'Ilustración de demostración: DEMO · Chaqueta de lino Choroní', true),
('falda-lino-macuto', 'falda-lino-macuto', 'DEMO · Falda de lino Macuto', 'demo-faldas', 'Producto ficticio de demostración. No es inventario real y no está disponible para compra. Falda de lino con cintura elástica y bolsillos laterales.', '', '', 3000, 'https://reinaldogocode.github.io/ProyectOne/demo-products/falda-lino-macuto.svg', 'Ilustración de demostración: DEMO · Falda de lino Macuto', true),
('falda-midi-tucacas', 'falda-midi-tucacas', 'DEMO · Falda midi Tucacas', 'demo-faldas', 'Producto ficticio de demostración. No es inventario real y no está disponible para compra. Falda midi de cintura alta con abertura lateral.', '', '', 3200, 'https://reinaldogocode.github.io/ProyectOne/demo-products/falda-midi-tucacas.svg', 'Ilustración de demostración: DEMO · Falda midi Tucacas', true),
('falda-plisada-porlamar', 'falda-plisada-porlamar', 'DEMO · Falda plisada Porlamar', 'demo-faldas', 'Producto ficticio de demostración. No es inventario real y no está disponible para compra. Falda plisada de vuelo suave y elástico en la cintura.', '', '', 3400, 'https://reinaldogocode.github.io/ProyectOne/demo-products/falda-plisada-porlamar.svg', 'Ilustración de demostración: DEMO · Falda plisada Porlamar', true),
('franela-pique-coro', 'franela-pique-coro', 'DEMO · Franela piqué Coro', 'demo-superiores', 'Producto ficticio de demostración. No es inventario real y no está disponible para compra. Franela de piqué con cuello camisero. Básico de todos los días.', '', '', 2200, 'https://reinaldogocode.github.io/ProyectOne/demo-products/franela-pique-coro.svg', 'Ilustración de demostración: DEMO · Franela piqué Coro', true),
('jean-recto-maracaibo', 'jean-recto-maracaibo', 'DEMO · Jean recto Maracaibo', 'demo-pantalones', 'Producto ficticio de demostración. No es inventario real y no está disponible para compra. Jean de tiro alto y pierna recta, con poco elastano.', '', '', 4000, 'https://reinaldogocode.github.io/ProyectOne/demo-products/jean-recto-maracaibo.svg', 'Ilustración de demostración: DEMO · Jean recto Maracaibo', true),
('pantalon-cargo-caracas', 'pantalon-cargo-caracas', 'DEMO · Pantalón cargo Caracas', 'demo-pantalones', 'Producto ficticio de demostración. No es inventario real y no está disponible para compra. Pantalón cargo con bolsillos laterales y puños ajustables.', '', '', 3600, 'https://reinaldogocode.github.io/ProyectOne/demo-products/pantalon-cargo-caracas.svg', 'Ilustración de demostración: DEMO · Pantalón cargo Caracas', true),
('pantalon-palazzo-merida', 'pantalon-palazzo-merida', 'DEMO · Pantalón palazzo Mérida', 'demo-pantalones', 'Producto ficticio de demostración. No es inventario real y no está disponible para compra. Pantalón palazzo de cintura alta y pierna ancha.', '', '', 3000, 'https://reinaldogocode.github.io/ProyectOne/demo-products/pantalon-palazzo-merida.svg', 'Ilustración de demostración: DEMO · Pantalón palazzo Mérida', true),
('pantalon-sastre-barquisimeto', 'pantalon-sastre-barquisimeto', 'DEMO · Pantalón sastre Barquisimeto', 'demo-pantalones', 'Producto ficticio de demostración. No es inventario real y no está disponible para compra. Pantalón sastre de pinza frontal y pierna recta.', '', '', 3800, 'https://reinaldogocode.github.io/ProyectOne/demo-products/pantalon-sastre-barquisimeto.svg', 'Ilustración de demostración: DEMO · Pantalón sastre Barquisimeto', true),
('pantalon-wide-leg-valencia', 'pantalon-wide-leg-valencia', 'DEMO · Pantalón wide leg Valencia', 'demo-pantalones', 'Producto ficticio de demostración. No es inventario real y no está disponible para compra. Pantalón wide leg de lino. Fuera de temporada por ahora.', '', '', 3300, 'https://reinaldogocode.github.io/ProyectOne/demo-products/pantalon-wide-leg-valencia.svg', 'Ilustración de demostración: DEMO · Pantalón wide leg Valencia', false),
('top-punto-lecheria', 'top-punto-lecheria', 'DEMO · Top de punto Lechería', 'demo-superiores', 'Producto ficticio de demostración. No es inventario real y no está disponible para compra. Top de punto acanalado con tirantes finos y escote cuadrado.', '', '', 1800, 'https://reinaldogocode.github.io/ProyectOne/demo-products/top-punto-lecheria.svg', 'Ilustración de demostración: DEMO · Top de punto Lechería', true),
('vestido-camisero-cumarebo', 'vestido-camisero-cumarebo', 'DEMO · Vestido camisero Cumarebo', 'demo-vestidos', 'Producto ficticio de demostración. No es inventario real y no está disponible para compra. Vestido camisero de lino con cinturón, botones y bolsillos.', '', '', 4000, 'https://reinaldogocode.github.io/ProyectOne/demo-products/vestido-camisero-cumarebo.svg', 'Ilustración de demostración: DEMO · Vestido camisero Cumarebo', true),
('vestido-corto-paraguana', 'vestido-corto-paraguana', 'DEMO · Vestido corto Paraguaná', 'demo-vestidos', 'Producto ficticio de demostración. No es inventario real y no está disponible para compra. Vestido corto de tirantes ajustables para el día a día.', '', '', 3400, 'https://reinaldogocode.github.io/ProyectOne/demo-products/vestido-corto-paraguana.svg', 'Ilustración de demostración: DEMO · Vestido corto Paraguaná', true),
('vestido-lino-isla', 'vestido-lino-isla', 'DEMO · Vestido de lino Isla', 'demo-vestidos', 'Producto ficticio de demostración. No es inventario real y no está disponible para compra. Vestido largo de lino, escote cuadrado y bolsillos laterales. Agotado por ahora.', '', '', 4200, 'https://reinaldogocode.github.io/ProyectOne/demo-products/vestido-lino-isla.svg', 'Ilustración de demostración: DEMO · Vestido de lino Isla', false),
('vestido-midi-canaima', 'vestido-midi-canaima', 'DEMO · Vestido midi Canaima', 'demo-vestidos', 'Producto ficticio de demostración. No es inventario real y no está disponible para compra. Vestido midi con cintura marcada y falda fluida.', '', '', 3800, 'https://reinaldogocode.github.io/ProyectOne/demo-products/vestido-midi-canaima.svg', 'Ilustración de demostración: DEMO · Vestido midi Canaima', true)
